insert into public.portfolios (student_name, display_name, class_name, course_code, branch_location, before_image_url, after_image_url, before_label, after_label, teacher_name, teacher_avatar_url, teacher_note, assessments, duration_label, parent_consent, is_published) values
  ('Trần Gia Bảo', 'Bé Gia Bảo', 'Lớp 1', 'LUYEN_CHU_DEP', 'XA_LA', 'https://picsum.photos/seed/thedu-lcd-giabao/600/800?grayscale&blur=2', 'https://picsum.photos/seed/thedu-lcd-giabao/600/800', 'Nét chữ cũ', 'Nét chữ chuẩn nét thanh nét đậm', 'Cô Hường', 'https://i.pravatar.cc/200?img=47', 'Ngày đầu Gia Bảo cầm bút còn gồng tay, chữ to nhỏ không đều. Sau 2 tháng con đã viết đúng độ cao, nét khuyết thẳng và biết nhấn nét thanh – nét đậm. Con rất kiên nhẫn, ba mẹ yên tâm nhé!', '[{"skill":"Độ đều nét","before":2,"after":4},{"skill":"Nét thanh – nét đậm","before":1,"after":4},{"skill":"Tư thế ngồi & cầm bút","before":2,"after":5},{"skill":"Trình bày vở sạch","before":2,"after":4}]'::jsonb, '2 tháng', true, true),
  ('Vũ Ngọc Hân', 'Bé Ngọc Hân', 'Lớp 2', 'LUYEN_CHU_DEP', 'NGO_THI_NHAM', 'https://picsum.photos/seed/thedu-lcd-ngochan/600/800?grayscale&blur=2', 'https://picsum.photos/seed/thedu-lcd-ngochan/600/800', 'Chữ viết vội, sai độ cao', 'Chữ nghiêng đều, vở sạch', 'Cô Hường', 'https://i.pravatar.cc/200?img=47', 'Ngọc Hân viết nhanh nhưng trước đây hay ẩu. Giờ con đã viết chữ nghiêng đều, khoảng cách hợp lý và vừa đạt giải Khuyến khích "Vở sạch – Chữ đẹp" cấp trường.', '[{"skill":"Độ đều nét","before":3,"after":5},{"skill":"Chữ nghiêng","before":2,"after":4},{"skill":"Tốc độ viết","before":4,"after":4},{"skill":"Trình bày vở sạch","before":2,"after":5}]'::jsonb, '3 tháng', true, true),
  ('Lê Khánh Linh', 'Bé Khánh Linh', 'Lớp 2', 'TOAN_TU_DUY', 'XA_LA', 'https://picsum.photos/seed/thedu-ttd-khanhlinh/600/800?grayscale&blur=2', 'https://picsum.photos/seed/thedu-ttd-khanhlinh/600/800', 'Trắc nghiệm đầu vào: 5/10', 'Bài kiểm tra hiện tại: 10/10', 'Thầy Tú', 'https://i.pravatar.cc/200?img=12', 'Khánh Linh từng mất 12 phút cho 20 phép tính, giờ chỉ còn 4 phút và không sai câu nào. Điều thầy vui nhất là con đã tự tin giơ tay giải bài trước lớp.', '[{"skill":"Tốc độ tính nhẩm","before":2,"after":5},{"skill":"Đọc hiểu đề toán","before":2,"after":4},{"skill":"Tư duy logic","before":3,"after":4},{"skill":"Sự tự tin","before":2,"after":5}]'::jsonb, '3 tháng', true, true),
  ('Đỗ Bảo Nam', 'Bé Bảo Nam', 'Lớp 1', 'TOAN_TU_DUY', 'XA_LA', 'https://picsum.photos/seed/thedu-ttd-baonam/600/800?grayscale&blur=2', 'https://picsum.photos/seed/thedu-ttd-baonam/600/800', 'Trắc nghiệm đầu vào: 4/10', 'Giải toán có lời văn 2 bước', 'Thầy Tú', 'https://i.pravatar.cc/200?img=12', 'Bảo Nam ban đầu chưa hiểu đề có lời văn. Sau 2 tháng con đã biết tóm tắt đề, tự vẽ sơ đồ và giải bài 2 bước mà không cần gợi ý.', '[{"skill":"Tốc độ tính nhẩm","before":2,"after":4},{"skill":"Đọc hiểu đề toán","before":1,"after":4},{"skill":"Tư duy logic","before":2,"after":4},{"skill":"Sự tập trung","before":2,"after":4}]'::jsonb, '2 tháng', true, true),
  ('Nguyễn Minh Anh', 'Bé Minh Anh', 'Mầm non 5 tuổi', 'TIEN_TIEU_HOC', 'NGO_THI_NHAM', 'https://picsum.photos/seed/thedu-tth-minhanh/600/800?grayscale&blur=2', 'https://picsum.photos/seed/thedu-tth-minhanh/600/800', 'Chưa cầm bút đúng', 'Tự viết tên & 29 chữ cái', 'Cô Hường', 'https://i.pravatar.cc/200?img=47', 'Minh Anh vào lớp còn rụt rè, chưa cầm bút đúng. Giờ con đã tự viết tên mình, đọc trơn 29 chữ cái và rất hào hứng mỗi buổi đến lớp.', '[{"skill":"Cầm bút đúng cách","before":1,"after":5},{"skill":"Nhận biết chữ cái","before":2,"after":5},{"skill":"Đếm & nhận biết số","before":3,"after":5},{"skill":"Nề nếp lớp học","before":2,"after":4}]'::jsonb, '2 tháng', true, true),
  ('Phạm Đức Huy', 'Bé Đức Huy', 'Mầm non 5 tuổi', 'TIEN_TIEU_HOC', 'XA_LA', 'https://picsum.photos/seed/thedu-tth-duchuy/600/800?grayscale&blur=2', 'https://picsum.photos/seed/thedu-tth-duchuy/600/800', 'Nét chữ run, chưa đúng ô li', 'Viết đúng ô li, nét liền mạch', 'Cô Hường', 'https://i.pravatar.cc/200?img=47', 'Đức Huy hiếu động, lúc đầu ngồi được 5 phút là muốn đứng dậy. Sau 3 tháng con đã ngồi học trọn buổi, viết đúng ô li và sẵn sàng vào lớp 1.', '[{"skill":"Cầm bút đúng cách","before":2,"after":4},{"skill":"Viết đúng ô li","before":1,"after":4},{"skill":"Sự tập trung","before":1,"after":4},{"skill":"Nề nếp lớp học","before":2,"after":5}]'::jsonb, '3 tháng', true, true);
